59	}
60	
61	// Ticket 为维修工单。Assignee 为当前（或终结前最后）负责人，空表示未派工；
62	// AssignedAt/AssignNote 为最近一次派工的变更时间与说明。
63	type Ticket struct {
64		ID           string `json:"id"`
65		AssetID      string `json:"asset_id"`
66		Description  string `json:"description"`
67		RequestID    string `json:"request_id"`
68		Status       string `json:"status"`
69		Result       string `json:"result,omitempty"`
70		CreatedAt    string `json:"created_at"`
71		ClosedAt     string `json:"closed_at,omitempty"`
72		CancelReason string `json:"cancel_reason,omitempty"`
73		CancelledAt  string `json:"cancelled_at,omitempty"`
74		Assignee     string `json:"assignee,omitempty"`
75		AssignedAt   string `json:"assigned_at,omitempty"`
76		AssignNote   string `json:"assign_note,omitempty"`
77	}
78	
79	// Event 为履历条目（报修/派工/关闭/取消/停用/恢复使用/保养建立/保养完成/保养撤销/领用/退回/附件登记/附件撤销），Seq 决定操作发生顺序。
80	// From/To 在派工履历中为原负责人（首次派工为空，展示为“未派工”）与新负责人；
81	// 在停用、恢复使用履历中为原资产状态与新资产状态。
82	// Due/Done/Interval 仅保养履历使用：建立履历含首次到期日（Due）与间隔天数
83	// （Interval），完成履历含周期到期日（Due）与实际完成日（Done）。
84	// TargetSeq 仅保养撤销履历使用：被撤销的完成履历的全库序号；完成身份以此序号
85	// 标识，不能用到期日或报修请求标识代替。
86	// PartID/Quantity/WithdrawalID 仅备件履历使用：领用与退回履历都携带备件编号、
87	// 数量与所属领用编号；Content 分别为领用说明与退回理由。
88	// AttachmentID/Path 仅附件履历使用：登记与撤销履历都携带附件编号与保存的绝对
89	// 路径；Content 分别为附件说明与撤销理由。
90	type Event struct {
91		Seq          int       `json:"-"`
92		AssetID      string    `json:"-"`
