99		Done         string    `json:"-"`
100		Interval     int       `json:"-"`
101		TargetSeq    int       `json:"-"`
102		PartID       string    `json:"-"`
103		Quantity     int       `json:"-"`
104		WithdrawalID string    `json:"-"`
105		AttachmentID string    `json:"-"`
106		Path         string    `json:"-"`
107		Time         time.Time `json:"-"`
108	}
