110	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
111	type eventJSON struct {
112		Seq          int    `json:"seq"`
113		AssetID      string `json:"asset_id"`
114		TicketID     string `json:"ticket_id,omitempty"`
115		Kind         string `json:"kind"`
116		Content      string `json:"content"`
117		From         string `json:"from,omitempty"`
118		To           string `json:"to,omitempty"`
119		Due          string `json:"due,omitempty"`
120		Done         string `json:"done,omitempty"`
121		Interval     int    `json:"interval,omitempty"`
122		TargetSeq    int    `json:"target_seq,omitempty"`
123		PartID       string `json:"part_id,omitempty"`
124		Quantity     int    `json:"quantity,omitempty"`
125		WithdrawalID string `json:"withdrawal_id,omitempty"`
126		AttachmentID string `json:"attachment_id,omitempty"`
127		Path         string `json:"path,omitempty"`
128		Time         string `json:"time"`
129	}
130	
131	func (e Event) toJSON() eventJSON {
132		return eventJSON{
133			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
134			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
135			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
136			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
137			AttachmentID: e.AttachmentID, Path: e.Path,
138			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
139			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
140			// 在重新保存（含导入合并后的提交）时也不会被截断。
141			Time: e.Time.Format(time.RFC3339Nano),
142		}
143	}
144	
145	func (e eventJSON) toEvent() (Event, error) {
146		t, err := time.Parse(time.RFC3339, e.Time)
147		if err != nil {
148			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
149		}
150		return Event{
151			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
152			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
153			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
154			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
155			AttachmentID: e.AttachmentID, Path: e.Path,
156			Time: t,
157		}, nil
158	}
159	
160	// PartWithdrawal 为一笔备件领用记录，ID 即领用编号（同目录唯一、不复用）。
161	// 数量表示工单用量；Returned 为累计退回数量，净量 = Quantity - Returned。
162	// 工单关闭或取消后记录与净量保留，不清零。
163	type PartWithdrawal struct {
164		ID       string `json:"id"`
165		TicketID string `json:"ticket_id"`
166		AssetID  string `json:"asset_id"`
167		PartID   string `json:"part_id"`
168		Quantity int    `json:"quantity"`
169		Note     string `json:"note"`
170		Returned int    `json:"returned"`
171	}
172	
173	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
174	// 它既不是资产编号也不是工单编号。
175	type requestBinding struct {
176		RequestID   string `json:"request_id"`
177		AssetID     string `json:"asset_id"`
178		Description string `json:"description"`
179		TicketID    string `json:"ticket_id"`
180	}
181	
182	// Attachment 为工单本地资料附件的索引记录，ID 即附件编号（同目录唯一、不复用）。
183	// 只保存引用：Path 为登记时解析得到的绝对路径，工具不复制、不修改、不删除
184	// 资料文件本身。撤销后保留记录、路径、说明（Note）与撤销理由（RevokeReason），
185	// 已撤销编号不能恢复；工单终结不自动撤销附件。
186	type Attachment struct {
187		ID           string `json:"id"`
188		TicketID     string `json:"ticket_id"`
189		AssetID      string `json:"asset_id"`
190		Path         string `json:"path"`
191		Note         string `json:"note"`
192		Revoked      bool   `json:"revoked"`
193		RevokeReason string `json:"revoke_reason,omitempty"`
194	}
195	
196	// storeData 是一次成功写操作共同生效的完整业务数据。
197	type storeData struct {
198		Version       int               `json:"version"`
199		Assets        []*Asset          `json:"assets"`
200		Tickets       []*Ticket         `json:"tickets"`
201		Events        []Event           `json:"-"`
202		EventsJSON    []eventJSON       `json:"events"`
203		Requests      []requestBinding  `json:"requests"`
204		Plans         []*Plan           `json:"plans"`
205		Parts         []*PartWithdrawal `json:"parts"`
206		Attachments   []*Attachment     `json:"attachments"`
207		NextTicketSeq int               `json:"next_ticket_seq"`
208		NextPartSeq   int               `json:"next_part_seq"`
209		NextAttachSeq int               `json:"next_attach_seq"`
210	}
211	
212	type store struct {
213		dir  string
214		data *storeData
215		now  func() time.Time
216	}
217	
218	func newStoreData() *storeData {
219		return &storeData{
220			Version:       storeVersion,
221			Assets:        []*Asset{},
222			Tickets:       []*Ticket{},
223			Events:        []Event{},
224			EventsJSON:    []eventJSON{},
225			Requests:      []requestBinding{},
226			Plans:         []*Plan{},
227			Parts:         []*PartWithdrawal{},
228			Attachments:   []*Attachment{},
229			NextTicketSeq: 1,
230			NextPartSeq:   1,
231			NextAttachSeq: 1,
232		}
233	}
234	
235	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
236	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
237	func openStore(dir string) (*store, error) {
238		return loadStore(dir, true)
239	}
240	
241	// openSourceStore 以只读用途打开导入源数据目录：与 openStore 做同样的整库
242	// 一致性检查，但源台账必须已存在——不存在时报错，绝不能当空库初始化。
243	func openSourceStore(dir string) (*store, error) {
244		return loadStore(dir, false)
245	}
246	
247	func loadStore(dir string, allowMissing bool) (*store, error) {
248		path := filepath.Join(dir, dataFileName)
249		raw, err := os.ReadFile(path)
250		if err != nil {
251			if errors.Is(err, os.ErrNotExist) {
252				if allowMissing {
253					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
254				}
255				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
256			}
257			return nil, fmt.Errorf("读取数据文件失败: %w", err)
258		}
259		if len(bytes.TrimSpace(raw)) == 0 {
260			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
261		}
262		var d storeData
263		if err := json.Unmarshal(raw, &d); err != nil {
264			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
265		}
266		if d.EventsJSON != nil {
267			d.Events = make([]Event, len(d.EventsJSON))
268			for i, ej := range d.EventsJSON {
269				ev, err := ej.toEvent()
270				if err != nil {
271					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
272				}
273				d.Events[i] = ev
274			}
275		}
276		// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
277		if d.Plans == nil {
278			d.Plans = []*Plan{}
279		}
280		// 无备件字段的有效旧库直接使用：缺省视为没有任何备件领用记录，
281		// 领用编号计数器从 1 开始。
282		if d.Parts == nil {
283			d.Parts = []*PartWithdrawal{}
284		}
285		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
286			d.NextPartSeq = 1
287		}
288		// 无附件字段的有效旧库直接使用：缺省视为没有任何附件索引记录，
289		// 附件编号计数器从 1 开始。
290		if d.Attachments == nil {
291			d.Attachments = []*Attachment{}
292		}
293		if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
294			d.NextAttachSeq = 1
295		}
296		if err := validateData(&d); err != nil {
297			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
298		}
299		return &store{dir: dir, data: &d, now: time.Now}, nil
300	}
301	
302	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
303	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
304	func parseTicketSeq(id string) (int, bool) {
305		if !strings.HasPrefix(id, "T") {
306			return 0, false
307		}
308		n, err := strconv.Atoi(id[1:])
309		if err != nil || n < 1 {
310			return 0, false
311		}
312		if fmt.Sprintf("T%04d", n) != id {
313			return 0, false
314		}
315		return n, true
316	}
317	
318	// parsePartSeq 解析 P 加补零正整数序号形式的领用编号，返回序号。
319	// 编号必须与 fmt.Sprintf("P%04d", n)（n ≥ 1）完全一致，否则视为非法。
320	func parsePartSeq(id string) (int, bool) {
321		if !strings.HasPrefix(id, "P") {
322			return 0, false
323		}
324		n, err := strconv.Atoi(id[1:])
325		if err != nil || n < 1 {
326			return 0, false
327		}
328		if fmt.Sprintf("P%04d", n) != id {
329			return 0, false
330		}
331		return n, true
332	}
333	
334	// parseAttachSeq 解析 A 加补零正整数序号形式的附件编号，返回序号。
335	// 编号必须与 fmt.Sprintf("A%04d", n)（n ≥ 1）完全一致，否则视为非法。
336	func parseAttachSeq(id string) (int, bool) {
337		if !strings.HasPrefix(id, "A") {
338			return 0, false
339		}
340		n, err := strconv.Atoi(id[1:])
341		if err != nil || n < 1 {
342			return 0, false
343		}
344		if fmt.Sprintf("A%04d", n) != id {
345			return 0, false
346		}
347		return n, true
348	}
349	
350	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
351	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
352	// 不做任何修复：不补字段、不重编号、不删除记录。
353	func validateData(d *storeData) error {
354		if d.Version != storeVersion {
355			return fmt.Errorf("不支持的数据版本 %d", d.Version)
356		}
357		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil || d.Plans == nil || d.Parts == nil || d.Attachments == nil {
358			return errors.New("缺少必要的数据段")
359		}
360		assets := map[string]*Asset{}
361		for _, a := range d.Assets {
362			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
363				return errors.New("数据矛盾：存在字段不完整的资产记录")
364			}
365			if a.Status != statusAvailable && a.Status != statusRepairing && a.Status != statusDeactivated {
366				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
367			}
368			if assets[a.ID] != nil {
369				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
370			}
371			assets[a.ID] = a
372		}
373		tickets := map[string]*Ticket{}
374		maxTicketSeq := 0
375		for _, t := range d.Tickets {
376			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
377				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
378			}
379			n, ok := parseTicketSeq(t.ID)
380			if !ok {
381				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
382			}
383			if n > maxTicketSeq {
384				maxTicketSeq = n
385			}
386			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
387				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
388			}
389			if assets[t.AssetID] == nil {
390				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
391			}
392			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
393				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
394			}
395			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
396				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
397			}
398			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
399				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
400			}
401			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
402				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
403			}
404			if t.Assignee == "" {
405				if t.AssignedAt != "" || t.AssignNote != "" {
406					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
407				}
408			} else if t.AssignedAt == "" || t.AssignNote == "" {
409				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
410			}
411			if tickets[t.ID] != nil {
412				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
413			}
414			tickets[t.ID] = t
415		}
416		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
417		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
418			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
419				d.NextTicketSeq, maxTicketSeq)
420		}
421		// 备件领用记录：编号唯一且为 P 加补零正整数序号，归属存在的工单且资产归属
422		// 与工单一致，数量为正，累计退回在 [0, 原数量] 内；与履历的接续在下方按
423		// 履历序号重放时核对。
424		parts := map[string]*PartWithdrawal{}
425		maxPartSeq := 0
426		for _, p := range d.Parts {
427			if p == nil || p.ID == "" || p.TicketID == "" || p.AssetID == "" || p.PartID == "" || p.Note == "" {
428				return errors.New("数据矛盾：存在字段不完整的备件领用记录")
429			}
430			n, ok := parsePartSeq(p.ID)
431			if !ok {
432				return fmt.Errorf("计数器矛盾：领用编号 %q 不是 P 加补零正整数序号的形式", p.ID)
433			}
434			if n > maxPartSeq {
435				maxPartSeq = n
436			}
437			if p.Quantity < 1 {
438				return fmt.Errorf("数据矛盾：领用记录 %s 的数量 %d 不是正整数", p.ID, p.Quantity)
439			}
440			if p.Returned < 0 || p.Returned > p.Quantity {
441				return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回 %d 超出原数量 %d", p.ID, p.Returned, p.Quantity)
442			}
443			t := tickets[p.TicketID]
444			if t == nil {
445				return fmt.Errorf("数据矛盾：领用记录 %s 引用了不存在的工单 %s", p.ID, p.TicketID)
446			}
447			if t.AssetID != p.AssetID {
448				return fmt.Errorf("数据矛盾：领用记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
449					p.ID, p.AssetID, t.ID, t.AssetID)
450			}
451			if parts[p.ID] != nil {
452				return fmt.Errorf("数据矛盾：领用编号 %s 重复", p.ID)
453			}
454			parts[p.ID] = p
455		}
456		// 下一领用序号必须为正并大于全部已用序号（允许有间隔）。
457		if d.NextPartSeq < 1 || d.NextPartSeq <= maxPartSeq {
458			return fmt.Errorf("计数器矛盾：下一领用序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
459				d.NextPartSeq, maxPartSeq)
460		}
461		// 附件索引记录：编号唯一且为 A 加补零正整数序号，归属存在的工单且资产归属
462		// 与工单一致，路径为绝对路径，说明非空；撤销状态与理由相互呼应。文件当前
463		// 是否可用不参与整库一致性校验；与履历的接续在下方按履历序号重放时核对。
464		attachments := map[string]*Attachment{}
465		maxAttachSeq := 0
466		for _, a := range d.Attachments {
467			if a == nil || a.ID == "" || a.TicketID == "" || a.AssetID == "" || a.Path == "" || a.Note == "" {
468				return errors.New("数据矛盾：存在字段不完整的附件记录")
469			}
470			n, ok := parseAttachSeq(a.ID)
471			if !ok {
472				return fmt.Errorf("计数器矛盾：附件编号 %q 不是 A 加补零正整数序号的形式", a.ID)
473			}
474			if n > maxAttachSeq {
475				maxAttachSeq = n
476			}
477			if !filepath.IsAbs(a.Path) {
478				return fmt.Errorf("数据矛盾：附件记录 %s 的路径 %q 不是绝对路径", a.ID, a.Path)
479			}
480			t := tickets[a.TicketID]
481			if t == nil {
482				return fmt.Errorf("数据矛盾：附件记录 %s 引用了不存在的工单 %s", a.ID, a.TicketID)
483			}
484			if t.AssetID != a.AssetID {
485				return fmt.Errorf("数据矛盾：附件记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
486					a.ID, a.AssetID, t.ID, t.AssetID)
487			}
488			if a.Revoked && a.RevokeReason == "" {
489				return fmt.Errorf("状态矛盾：已撤销附件 %s 缺少撤销理由", a.ID)
490			}
491			if !a.Revoked && a.RevokeReason != "" {
492				return fmt.Errorf("状态矛盾：有效附件 %s 不应带有撤销理由", a.ID)
493			}
494			if attachments[a.ID] != nil {
495				return fmt.Errorf("数据矛盾：附件编号 %s 重复", a.ID)
496			}
497			attachments[a.ID] = a
498		}
499		// 下一附件序号必须为正并大于全部已用序号（允许有间隔）。
500		if d.NextAttachSeq < 1 || d.NextAttachSeq <= maxAttachSeq {
501			return fmt.Errorf("计数器矛盾：下一附件序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
502				d.NextAttachSeq, maxAttachSeq)
503		}
504		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
505		boundReq := map[string]bool{}
506		boundTicket := map[string]bool{}
507		for _, r := range d.Requests {
508			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
509				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
510			}
511			if boundReq[r.RequestID] {
512				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
513			}
514			boundReq[r.RequestID] = true
515			t := tickets[r.TicketID]
516			if t == nil {
517				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
518			}
519			if t.RequestID != r.RequestID {
520				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
521					r.TicketID, t.RequestID, r.RequestID)
522			}
523			if r.AssetID != t.AssetID || r.Description != t.Description {
524				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
525					r.RequestID, t.ID)
526			}
527			boundTicket[r.TicketID] = true
528		}
529		for _, t := range d.Tickets {
530			if !boundTicket[t.ID] {
531				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
532			}
533		}
534		// 状态：每项资产最多一张未关闭工单，有则必须为“维修中”；无未关闭工单时
535		// 资产可为“可用”或“停用”，停用与否由停用、恢复使用履历链决定，在下方
536		// 按履历序号重放时核对。
537		openCount := map[string]int{}
538		for _, t := range d.Tickets {
539			if t.Status == ticketOpen {
540				openCount[t.AssetID]++
541			}
542		}
543		for _, a := range d.Assets {
544			c := openCount[a.ID]
545			if c > 1 {
546				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
547			}
548			if c == 1 {
549				if a.Status != statusRepairing {
550					return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
551						a.ID, c, statusRepairing, a.Status)
552				}
553				continue
554			}
555			if a.Status != statusAvailable && a.Status != statusDeactivated {
556				return fmt.Errorf("状态矛盾：资产 %s 没有未关闭工单，状态应为 %s 或 %s，实际为 %s",
557					a.ID, statusAvailable, statusDeactivated, a.Status)
558			}
559		}
560		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
561		seenSeq := map[int]bool{}
562		reportSeq := map[string]int{}
563		closeSeq := map[string]int{}
564		cancelSeq := map[string]int{}
565		reportCount := map[string]int{}
566		closeCount := map[string]int{}
567		cancelCount := map[string]int{}
568		for i := range d.Events {
569			e := &d.Events[i]
570			if e.Seq < 1 {
571				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
572			}
573			if seenSeq[e.Seq] {
574				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
575			}
576			seenSeq[e.Seq] = true
577			if e.AssetID == "" || e.Kind == "" || e.Content == "" {
578				return errors.New("履历矛盾：存在字段不完整的履历记录")
579			}
580			if e.Kind == eventPlanCreate || e.Kind == eventPlanDone || e.Kind == eventPlanRevoke {
581				// 保养履历：不属于任何工单，不携带派工字段；日期与间隔在此核对，
582				// 建立、完成及撤销链的接续在下方按序号重放时核对。
583				if e.TicketID != "" || e.From != "" || e.To != "" {
584					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号或派工人员字段", e.Seq, e.Kind)
585				}
586				if e.Kind == eventPlanRevoke {
587					// 撤销履历：内容即撤销理由（非空已检查），仅携带目标完成履历序号。
588					if e.Due != "" || e.Done != "" || e.Interval != 0 {
589						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录不应带有到期日、完成日或间隔天数", e.Seq)
590					}
591					if e.TargetSeq < 1 {
592						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录目标完成履历序号须为正整数", e.Seq)
593					}
594					continue
595				}
596				if e.TargetSeq != 0 {
597					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有目标完成履历序号", e.Seq, e.Kind)
598				}
599				due, err := parseDate(e.Due)
600				if err != nil {
601					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录到期日无效", e.Seq, e.Kind)
602				}
603				if e.Kind == eventPlanCreate {
604					if e.Done != "" {
605						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录不应带有完成日", e.Seq)
606					}
607					if e.Interval < 1 {
608						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录间隔天数须为正整数", e.Seq)
609					}
610				} else {
611					if e.Interval != 0 {
612						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录不应带有间隔天数", e.Seq)
613					}
614					done, err := parseDate(e.Done)
615					if err != nil {
616						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录完成日无效", e.Seq)
617					}
618					if done < due {
619						return fmt.Errorf("履历矛盾：履历序号 %d 的完成日早于周期到期日", e.Seq)
620					}
621				}
622				continue
623			}
624			if e.Kind == eventDeactivate || e.Kind == eventReactivate {
625				// 停用/恢复使用为资产级履历：不属于任何工单，From/To 为原状态与新
626				// 状态，不携带派工、保养、备件或附件字段。转换是否接续（可用->停用、
627				// 停用->可用）在下方按履历序号重放时核对。
628				if e.TicketID != "" {
629					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号", e.Seq, e.Kind)
630				}
631				if e.From == "" || e.To == "" {
632					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少原状态或新状态", e.Seq, e.Kind)
633				}
634				if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 ||
635					e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
636					e.AttachmentID != "" || e.Path != "" {
637					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有保养、备件或附件字段", e.Seq, e.Kind)
638				}
639				if assets[e.AssetID] == nil {
640					return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产", e.Seq)
641				}
642				continue
643			}
644			if e.TicketID == "" {
645				return errors.New("履历矛盾：存在字段不完整的履历记录")
646			}
647			if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 {
648				return fmt.Errorf("履历矛盾：履历序号 %d 的维修履历不应带有保养字段", e.Seq)
649			}
650			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
651				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
652			}
653			if e.Kind == eventAssign {
654				if e.To == "" {
655					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
656				}
657				if e.From == e.To {
658					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
659				}
660			}
661			// 附件字段仅附件履历携带；附件履历不携带备件字段。
662			if e.Kind != eventAttach && e.Kind != eventAttachRevoke && (e.AttachmentID != "" || e.Path != "") {
663				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有附件编号或路径", e.Seq, e.Kind)
664			}
665			if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) &&
666				(e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "") {
667				return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件字段", e.Seq, e.Kind)
668			}
669			t := tickets[e.TicketID]
670			if t == nil || assets[e.AssetID] == nil {
671				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
672			}
673			if e.AssetID != t.AssetID {
674				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
675					e.Seq, e.AssetID, t.ID, t.AssetID)
676			}
677			switch e.Kind {
678			case eventReport:
679				if e.Content != t.Description {
680					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
681				}
682				reportCount[t.ID]++
683				reportSeq[t.ID] = e.Seq
684			case eventClose:
685				if e.Content != t.Result {
686					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
687				}
688				closeCount[t.ID]++
689				closeSeq[t.ID] = e.Seq
690			case eventCancel:
691				if e.Content != t.CancelReason {
692					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
693				}
694				cancelCount[t.ID]++
695				cancelSeq[t.ID] = e.Seq
696			case eventAssign:
697				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
698				// 在下方按序号重放时核对。
699			case eventPartWithdraw, eventPartReturn:
700				// 内容即领用说明或退回理由（非空已检查）；备件字段在此核对，
701				// 与领用记录的接续及累计退回在下方按序号重放时核对。
702				if e.PartID == "" || e.WithdrawalID == "" {
703					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少备件编号或领用编号", e.Seq, e.Kind)
704				}
705				if e.Quantity < 1 {
706					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录数量 %d 不是正整数", e.Seq, e.Kind, e.Quantity)
707				}
708				if _, ok := parsePartSeq(e.WithdrawalID); !ok {
709					return fmt.Errorf("履历矛盾：履历序号 %d 的领用编号 %q 不是 P 加补零正整数序号的形式",
710						e.Seq, e.WithdrawalID)
711				}
712			case eventAttach, eventAttachRevoke:
713				// 内容即附件说明或撤销理由（非空已检查）；附件字段在此核对，
714				// 与附件记录的接续及登记、撤销顺序在下方按序号重放时核对。
715				if e.AttachmentID == "" || e.Path == "" {
716					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少附件编号或路径", e.Seq, e.Kind)
717				}
718				if _, ok := parseAttachSeq(e.AttachmentID); !ok {
719					return fmt.Errorf("履历矛盾：履历序号 %d 的附件编号 %q 不是 A 加补零正整数序号的形式",
720						e.Seq, e.AttachmentID)
721				}
722				if !filepath.IsAbs(e.Path) {
723					return fmt.Errorf("履历矛盾：履历序号 %d 的附件路径 %q 不是绝对路径", e.Seq, e.Path)
724				}
725			default:
726				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
727			}
728		}
729		for _, t := range d.Tickets {
730			if reportCount[t.ID] != 1 {
731				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
732			}
733			if t.Status == ticketClosed {
734				if closeCount[t.ID] != 1 {
735					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
736				}
737				if closeSeq[t.ID] <= reportSeq[t.ID] {
738					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
739						t.ID, closeSeq[t.ID], reportSeq[t.ID])
740				}
741			} else if closeCount[t.ID] != 0 {
742				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
743			}
744			if t.Status == ticketCancelled {
745				if cancelCount[t.ID] != 1 {
746					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
747				}
748				if cancelSeq[t.ID] <= reportSeq[t.ID] {
749					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
750						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
751				}
752			} else if cancelCount[t.ID] != 0 {
753				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
754			}
755		}
756		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
757		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
758		sorted := make([]Event, len(d.Events))
759		copy(sorted, d.Events)
760		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
761		derivedTicket := map[string]string{}
762		derivedOpen := map[string]string{}
763		derivedDeactivated := map[string]bool{}
764		derivedAssignee := map[string]string{}
765		derivedNote := map[string]string{}
766		withdrawSeq := map[string]int{}
767		derivedReturned := map[string]int{}
768		attachRegSeq := map[string]int{}
769		attachRevokeSeq := map[string]int{}
770		for _, e := range sorted {
771			switch e.Kind {
772			case eventReport:
773				if derivedTicket[e.TicketID] != "" {
774					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
775				}
776				if prev := derivedOpen[e.AssetID]; prev != "" {
777					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
778						e.AssetID, prev, e.TicketID)
779				}
780				if derivedDeactivated[e.AssetID] {
781					return fmt.Errorf("履历矛盾：资产 %s 在停用期间产生了工单 %s 的报修",
782						e.AssetID, e.TicketID)
783				}
784				derivedTicket[e.TicketID] = ticketOpen
785				derivedOpen[e.AssetID] = e.TicketID
786			case eventDeactivate:
787				// 停用要求当时“可用”（无未关闭工单且未停用）；维修中（有未关闭
788				// 工单）的资产不能停用。From/To 须与实际转换一致。
789				if derivedOpen[e.AssetID] != "" {
790					return fmt.Errorf("履历矛盾：资产 %s 在存在未关闭工单时出现停用履历（序号 %d）",
791						e.AssetID, e.Seq)
792				}
793				if derivedDeactivated[e.AssetID] {
794					return fmt.Errorf("履历矛盾：资产 %s 被重复停用（序号 %d）", e.AssetID, e.Seq)
795				}
796				if e.From != statusAvailable || e.To != statusDeactivated {
797					return fmt.Errorf("履历矛盾：停用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
798						e.Seq, statusAvailable, statusDeactivated, e.From, e.To)
799				}
800				derivedDeactivated[e.AssetID] = true
801			case eventReactivate:
802				// 恢复使用只作用于停用资产；From/To 须与实际转换一致。
803				if !derivedDeactivated[e.AssetID] {
804					return fmt.Errorf("履历矛盾：资产 %s 未停用却出现恢复使用履历（序号 %d）", e.AssetID, e.Seq)
805				}
806				if derivedOpen[e.AssetID] != "" {
807					return fmt.Errorf("履历矛盾：资产 %s 恢复使用（序号 %d）时仍存在未关闭工单",
808						e.AssetID, e.Seq)
809				}
810				if e.From != statusDeactivated || e.To != statusAvailable {
811					return fmt.Errorf("履历矛盾：恢复使用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
812						e.Seq, statusDeactivated, statusAvailable, e.From, e.To)
813				}
814				delete(derivedDeactivated, e.AssetID)
815			case eventAssign:
816				if derivedTicket[e.TicketID] != ticketOpen {
817					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
818				}
819				if e.From != derivedAssignee[e.TicketID] {
820					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
821						e.TicketID, e.Seq, e.From)
822				}
823				derivedAssignee[e.TicketID] = e.To
824				derivedNote[e.TicketID] = e.Content
825			case eventClose:
826				if derivedTicket[e.TicketID] != ticketOpen {
827					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
828				}
829				derivedTicket[e.TicketID] = ticketClosed
830				delete(derivedOpen, e.AssetID)
831			case eventCancel:
832				if derivedTicket[e.TicketID] != ticketOpen {
833					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
834				}
835				derivedTicket[e.TicketID] = ticketCancelled
836				delete(derivedOpen, e.AssetID)
837			case eventPartWithdraw:
838				// 领用须在报修之后、终结之前；履历与领用记录的业务字段必须一致。
839				if derivedTicket[e.TicketID] != ticketOpen {
840					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现领用履历（序号 %d）",
841						e.TicketID, e.Seq)
842				}
843				p := parts[e.WithdrawalID]
844				if p == nil {
845					return fmt.Errorf("履历矛盾：领用履历（序号 %d）引用了不存在的领用记录 %s",
846						e.Seq, e.WithdrawalID)
847				}
848				if withdrawSeq[p.ID] != 0 {
849					return fmt.Errorf("履历矛盾：领用记录 %s 有多条领用履历", p.ID)
850				}
851				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID ||
852					p.Quantity != e.Quantity || p.Note != e.Content {
853					return fmt.Errorf("履历矛盾：领用履历（序号 %d）与领用记录 %s 的工单、资产、备件、数量或说明不一致",
854						e.Seq, p.ID)
855				}
856				withdrawSeq[p.ID] = e.Seq
857			case eventPartReturn:
858				// 退回须在报修之后、终结之前，且指向先前已领用的记录；
859				// 累计退回不得超过该笔原数量。
860				if derivedTicket[e.TicketID] != ticketOpen {
861					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现退回履历（序号 %d）",
862						e.TicketID, e.Seq)
863				}
864				p := parts[e.WithdrawalID]
865				if p == nil {
866					return fmt.Errorf("履历矛盾：退回履历（序号 %d）引用了不存在的领用记录 %s",
867						e.Seq, e.WithdrawalID)
868				}
869				if withdrawSeq[p.ID] == 0 {
870					return fmt.Errorf("履历矛盾：退回履历（序号 %d）出现在领用记录 %s 的领用履历之前",
871						e.Seq, p.ID)
872				}
873				if p.TicketID != e.TicketID || p.AssetID != e.AssetID || p.PartID != e.PartID {
874					return fmt.Errorf("履历矛盾：退回履历（序号 %d）与领用记录 %s 的工单、资产或备件不一致",
875						e.Seq, p.ID)
876				}
877				// 逐步核对累计退回不超过原数量：先做不会溢出的减法比较再累加。
878				// 直接相加可能整数溢出回绕，即使回绕后的累计恰好等于保存值，
879				// 实际超额的履历也必须拒绝。
880				if e.Quantity > p.Quantity-derivedReturned[p.ID] {
881					return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回在履历序号 %d 处超过原数量 %d",
882						p.ID, e.Seq, p.Quantity)
883				}
884				derivedReturned[p.ID] += e.Quantity
885			case eventAttach:
886				// 登记须在报修之后；未关闭、已关闭或已取消工单均可补充资料。
887				// 履历与附件记录的业务字段必须一致。
888				if derivedTicket[e.TicketID] == "" {
889					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件登记履历（序号 %d）",
890						e.TicketID, e.Seq)
891				}
892				a := attachments[e.AttachmentID]
893				if a == nil {
894					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）引用了不存在的附件记录 %s",
895						e.Seq, e.AttachmentID)
896				}
897				if attachRegSeq[a.ID] != 0 {
898					return fmt.Errorf("履历矛盾：附件记录 %s 有多条登记履历", a.ID)
899				}
900				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.Note != e.Content {
901					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）与附件记录 %s 的工单、资产、路径或说明不一致",
902						e.Seq, a.ID)
903				}
904				attachRegSeq[a.ID] = e.Seq
905			case eventAttachRevoke:
906				// 撤销须在登记之后，且每个附件至多撤销一次；
907				// 履历与附件记录的业务字段必须一致。
908				if derivedTicket[e.TicketID] == "" {
909					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件撤销履历（序号 %d）",
910						e.TicketID, e.Seq)
911				}
912				a := attachments[e.AttachmentID]
913				if a == nil {
914					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）引用了不存在的附件记录 %s",
915						e.Seq, e.AttachmentID)
916				}
917				if attachRegSeq[a.ID] == 0 {
918					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）出现在附件记录 %s 的登记履历之前",
919						e.Seq, a.ID)
920				}
921				if attachRevokeSeq[a.ID] != 0 {
922					return fmt.Errorf("履历矛盾：附件记录 %s 有多条撤销履历", a.ID)
923				}
924				if a.TicketID != e.TicketID || a.AssetID != e.AssetID || a.Path != e.Path || a.RevokeReason != e.Content {
925					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）与附件记录 %s 的工单、资产、路径或撤销理由不一致",
926						e.Seq, a.ID)
927				}
928				attachRevokeSeq[a.ID] = e.Seq
929			}
930		}
931		for _, t := range d.Tickets {
932			if derivedTicket[t.ID] != t.Status {
933				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
934					t.ID, derivedTicket[t.ID], t.Status)
935			}
936			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
937			if derivedAssignee[t.ID] != t.Assignee {
938				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
939					t.ID, derivedAssignee[t.ID], t.Assignee)
940			}
941			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
942				return fmt.Errorf("状态矛盾：工单 %s 保存的派工说明与最后一次派工履历不一致", t.ID)
943			}
944		}
945		// 每笔领用记录恰有一条领用履历；按履历重放得到的累计退回须与保存值一致。
946		for _, p := range d.Parts {
947			if withdrawSeq[p.ID] == 0 {
948				return fmt.Errorf("履历矛盾：领用记录 %s 缺少对应的领用履历", p.ID)
949			}
950			if derivedReturned[p.ID] != p.Returned {
951				return fmt.Errorf("备件数量矛盾：按履历推出领用记录 %s 的累计退回为 %d，与保存的 %d 不符",
952					p.ID, derivedReturned[p.ID], p.Returned)
953			}
954		}
955		// 每条附件记录恰有一条登记履历、至多一条撤销履历；记录的撤销状态须与
956		// 是否存在撤销履历一致。
957		for _, a := range d.Attachments {
958			if attachRegSeq[a.ID] == 0 {
959				return fmt.Errorf("履历矛盾：附件记录 %s 缺少对应的登记履历", a.ID)
960			}
961			if revoked := attachRevokeSeq[a.ID] != 0; revoked != a.Revoked {
962				return fmt.Errorf("状态矛盾：附件记录 %s 保存的撤销状态与履历不符", a.ID)
963			}
964		}
965		for _, a := range d.Assets {
966			want := statusAvailable
967			switch {
968			case derivedDeactivated[a.ID]:
969				want = statusDeactivated
970			case derivedOpen[a.ID] != "":
971				want = statusRepairing
972			}
973			if a.Status != want {
974				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
975					a.ID, want, a.Status)
976			}
977		}
978		// 保养计划：归属存在的资产、每项资产最多一个、日期有效、间隔为正整数。
979		plans := map[string]*Plan{}
980		for _, p := range d.Plans {
981			if p == nil || p.AssetID == "" || p.Content == "" {
982				return errors.New("数据矛盾：存在字段不完整的保养计划")
983			}
984			if assets[p.AssetID] == nil {
985				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
986			}
987			if plans[p.AssetID] != nil {
988				return fmt.Errorf("数据矛盾：资产 %s 有多个保养计划，最多允许一个", p.AssetID)
989			}
990			if _, err := parseDate(p.FirstDue); err != nil {
991				return fmt.Errorf("数据矛盾：资产 %s 保养计划的首次到期日无效", p.AssetID)
992			}
993			if p.IntervalDays < 1 {
994				return fmt.Errorf("数据矛盾：资产 %s 保养计划的间隔天数须为正整数", p.AssetID)
995			}
996			if _, err := parseDate(p.NextDue); err != nil {
997				return fmt.Errorf("数据矛盾：资产 %s 保养计划的下一到期日无效", p.AssetID)
998			}
999			plans[p.AssetID] = p
1000		}
1001		// 保养履历链：每个计划恰有一条建立履历（内容、首次到期日、间隔与计划一致），
1002		// 完成履历按序号接续（周期到期日须等于当时下一到期日，完成日不早于它），
1003		// 撤销履历须引用先前同资产、未撤销且当时最新有效的完成，并把下一到期日恢复
1004		// 为该完成的周期到期日；由履历推出的下一到期日须与计划保存的一致。
1005		// 没有计划的资产不得有保养履历。
1006		maintCreate := map[string]int{}
1007		derivedDue := map[string]string{}
1008		doneSeqs := map[string][]int{}
1009		doneDue := map[string]map[int]string{}
1010		revokedDone := map[int]bool{}
1011		// 停用状态随全库履历序号推进：停用期间不得登记保养完成；停用不暂停、不
1012		// 重算周期，因此建立、完成与撤销的接续规则本身不受影响。
1013		deactivatedAt := map[string]bool{}
1014		for _, e := range sorted {
1015			switch e.Kind {
1016			case eventDeactivate:
1017				deactivatedAt[e.AssetID] = true
1018				continue
1019			case eventReactivate:
1020				delete(deactivatedAt, e.AssetID)
1021				continue
1022			}
1023			if e.Kind != eventPlanCreate && e.Kind != eventPlanDone && e.Kind != eventPlanRevoke {
1024				continue
1025			}
1026			p := plans[e.AssetID]
1027			if p == nil {
1028				return fmt.Errorf("履历矛盾：资产 %s 没有保养计划，却存在保养履历（序号 %d）", e.AssetID, e.Seq)
1029			}
1030			if e.Kind == eventPlanCreate {
1031				if maintCreate[e.AssetID] != 0 {
1032					return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", e.AssetID)
1033				}
1034				maintCreate[e.AssetID] = e.Seq
1035				if e.Content != p.Content || e.Due != p.FirstDue || e.Interval != p.IntervalDays {
1036					return fmt.Errorf("履历矛盾：资产 %s 的保养建立履历与计划内容、首次到期日或间隔不一致", e.AssetID)
1037				}
1038				derivedDue[e.AssetID] = e.Due
1039				continue
1040			}
1041			if maintCreate[e.AssetID] == 0 {
1042				return fmt.Errorf("履历矛盾：资产 %s 的%s履历（序号 %d）出现在建立履历之前", e.AssetID, e.Kind, e.Seq)
1043			}
1044			if e.Kind == eventPlanRevoke {
1045				// 目标须为先前同资产的完成履历（更晚序号的完成此时尚未出现），
1046				// 未撤销且为当时最新有效；撤销后下一到期日恢复为其周期到期日。
1047				due, ok := doneDue[e.AssetID][e.TargetSeq]
1048				if !ok {
1049					return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是资产 %s 先前的完成履历",
1050						e.Seq, e.TargetSeq, e.AssetID)
1051				}
1052				if revokedDone[e.TargetSeq] {
1053					return fmt.Errorf("履历矛盾：完成履历序号 %d 被重复撤销（撤销履历序号 %d）", e.TargetSeq, e.Seq)
1054				}
1055				latest := 0
1056				for _, seq := range doneSeqs[e.AssetID] {
1057					if !revokedDone[seq] {
1058						latest = seq
1059					}
1060				}
1061				if latest != e.TargetSeq {
1062					return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是当时最新的有效完成（序号 %d）",
1063						e.Seq, e.TargetSeq, latest)
1064				}
1065				revokedDone[e.TargetSeq] = true
1066				derivedDue[e.AssetID] = due
1067				continue
1068			}
1069			if e.Kind == eventPlanDone && deactivatedAt[e.AssetID] {
1070				return fmt.Errorf("履历矛盾：资产 %s 在停用期间出现保养完成履历（序号 %d）",
1071					e.AssetID, e.Seq)
1072			}
1073			if e.Due != derivedDue[e.AssetID] {
1074				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
1075					e.AssetID, e.Seq, e.Due, derivedDue[e.AssetID])
1076			}
1077			first, _ := parseDate(p.FirstDue)
1078			done, _ := parseDate(e.Done)
1079			next, ok := nextDueAfter(first, int64(p.IntervalDays), done)
1080			if !ok {
1081				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
1082					e.AssetID, e.Seq)
1083			}
1084			derivedDue[e.AssetID] = formatDate(next)
1085			doneSeqs[e.AssetID] = append(doneSeqs[e.AssetID], e.Seq)
1086			if doneDue[e.AssetID] == nil {
1087				doneDue[e.AssetID] = map[int]string{}
1088			}
1089			doneDue[e.AssetID][e.Seq] = e.Due
1090		}
1091		for _, p := range d.Plans {
1092			if maintCreate[p.AssetID] == 0 {
1093				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
1094			}
1095			if derivedDue[p.AssetID] != p.NextDue {
1096				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
1097					p.AssetID, derivedDue[p.AssetID], p.NextDue)
1098			}
1099		}
1100		return nil
1101	}
