1103	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
1104	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
1105	// 保持不变，不留下部分业务变化。
1106	func (s *store) save() error {
1107		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
1108		for i, e := range s.data.Events {
1109			s.data.EventsJSON[i] = e.toJSON()
1110		}
1111		if err := validateData(s.data); err != nil {
1112			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
1113		}
1114		var buf bytes.Buffer
1115		enc := json.NewEncoder(&buf)
1116		enc.SetIndent("", "  ")
1117		if err := enc.Encode(s.data); err != nil {
1118			return fmt.Errorf("编码数据失败: %w", err)
1119		}
1120		if err := os.MkdirAll(s.dir, 0o755); err != nil {
1121			return fmt.Errorf("创建数据目录失败: %w", err)
1122		}
1123		path := filepath.Join(s.dir, dataFileName)
1124		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
1125		if err != nil {
1126			return fmt.Errorf("创建临时数据文件失败: %w", err)
1127		}
1128		tmpName := tmp.Name()
1129		abort := func(err error) error {
1130			_ = tmp.Close()
1131			_ = os.Remove(tmpName)
1132			return err
1133		}
1134		if _, err := tmp.Write(buf.Bytes()); err != nil {
1135			abort(nil)
1136			return fmt.Errorf("写入数据失败: %w", err)
1137		}
1138		if err := tmp.Sync(); err != nil {
1139			abort(nil)
1140			return fmt.Errorf("写入数据失败: %w", err)
1141		}
1142		if err := tmp.Close(); err != nil {
1143			_ = os.Remove(tmpName)
1144			return fmt.Errorf("写入数据失败: %w", err)
1145		}
1146		if err := os.Rename(tmpName, path); err != nil {
1147			_ = os.Remove(tmpName)
1148			return fmt.Errorf("保存数据失败: %w", err)
1149		}
1150		return nil
1151	}
