1200	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
1201	func (s *store) nextEventSeq() (int, error) {
1202		maxSeq := 0
1203		for _, e := range s.data.Events {
1204			if e.Seq > maxSeq {
1205				maxSeq = e.Seq
1206			}
1207		}
1208		if maxSeq == math.MaxInt {
1209			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
1210		}
1211		return maxSeq + 1, nil
1212	}
