1238	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
1239	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
1240	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
1241		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
1242		// 资产或描述不同 => 拒绝。
1243		if r := s.findRequest(requestID); r != nil {
1244			if r.AssetID != assetID || r.Description != description {
1245				return nil, false, fmt.Errorf(
1246					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
1247					errConflict, requestID, r.AssetID)
1248			}
1249			t := s.findTicket(r.TicketID)
1250			if t == nil {
1251				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
1252			}
1253			return t, true, nil
1254		}
1255	
1256		asset := s.findAsset(assetID)
1257		if asset == nil {
1258			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
1259		}
1260		if asset.Status == statusDeactivated {
1261			// 停用期间拒绝新报修，也不绑定新请求标识；恢复使用后可用同一标识重试。
1262			return nil, false, fmt.Errorf("%w: 资产 %s 已停用，不能报修", errConflict, assetID)
1263		}
1264		if t := s.openTicketOf(assetID); t != nil {
1265			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
1266		}
1267		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
1268		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
1269		seq := s.data.NextTicketSeq
1270		if seq < 1 || seq == math.MaxInt {
1271			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
1272		}
1273		eventSeq, err := s.nextEventSeq()
1274		if err != nil {
1275			return nil, false, err
1276		}
1277		t := &Ticket{
1278			ID:          fmt.Sprintf("T%04d", seq),
1279			AssetID:     assetID,
1280			Description: description,
1281			RequestID:   requestID,
1282			Status:      ticketOpen,
1283			CreatedAt:   s.now().Format(time.RFC3339),
1284		}
1285		s.data.NextTicketSeq = seq + 1
1286		s.data.Tickets = append(s.data.Tickets, t)
1287		s.data.Requests = append(s.data.Requests, requestBinding{
1288			RequestID:   requestID,
1289			AssetID:     assetID,
1290			Description: description,
1291			TicketID:    t.ID,
1292		})
1293		asset.Status = statusRepairing
1294		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
1295		return t, false, nil
1296	}
1297	
1298	// closeTicket 关闭未关闭工单并把资产恢复为可用。
1299	// 失败路径不修改任何业务数据。
1300	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1301		t := s.findTicket(ticketID)
1302		if t == nil {
1303			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1304		}
1305		if t.Status == ticketCancelled {
1306			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
1307		}
1308		if t.Status != ticketOpen {
1309			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
1310		}
1311		asset := s.findAsset(t.AssetID)
1312		if asset == nil {
1313			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1314		}
1315		eventSeq, err := s.nextEventSeq()
1316		if err != nil {
1317			return nil, nil, err
1318		}
1319		t.Status = ticketClosed
1320		t.Result = result
1321		t.ClosedAt = s.now().Format(time.RFC3339)
1322		asset.Status = statusAvailable
1323		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1324		return t, asset, nil
1325	}
1326	
1327	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
1328	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
1329	// 失败路径不修改任何业务数据。
1330	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1331		t := s.findTicket(ticketID)
1332		if t == nil {
1333			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1334		}
1335		if t.Status == ticketCancelled {
1336			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1337		}
1338		if t.Status == ticketClosed {
1339			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1340		}
1341		asset := s.findAsset(t.AssetID)
1342		if asset == nil {
1343			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1344		}
1345		eventSeq, err := s.nextEventSeq()
1346		if err != nil {
1347			return nil, nil, err
1348		}
1349		t.Status = ticketCancelled
1350		t.CancelReason = reason
1351		t.CancelledAt = s.now().Format(time.RFC3339)
1352		asset.Status = statusAvailable
1353		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1354		return t, asset, nil
1355	}
1356	
1357	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1358	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1359	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1360	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1361	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1362	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1363		t := s.findTicket(ticketID)
1364		if t == nil {
1365			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1366		}
1367		if t.Status == ticketClosed {
1368			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1369		}
1370		if t.Status == ticketCancelled {
1371			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1372		}
1373		if assignee == "" {
1374			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1375		}
1376		if note == "" {
1377			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1378		}
1379		if t.Assignee == assignee {
1380			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1381				errConflict, ticketID, assignee)
1382		}
1383		eventSeq, err := s.nextEventSeq()
1384		if err != nil {
1385			return nil, err
1386		}
1387		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1388		t.Assignee = assignee
1389		t.AssignedAt = s.now().Format(time.RFC3339)
1390		t.AssignNote = note
1391		return t, nil
1392	}
1393

