14	// 资产批量导入：把源数据目录中所选资产连同其全部工单、报修请求绑定、
15	// 报修/派工/关闭/取消履历、停用/恢复使用履历（含当前停用或可用状态）、备件
16	// 领用记录、附件索引（含登记/撤销履历）与保养计划（含保养建立/完成/撤销
17	// 履历）复制到目标数据目录。
18	//
19	// 关键规则：
20	//   - 导入是复制：源台账始终只读，不删除、不修改任何源记录；同一台账不能导入自身。
21	//   - 工单编号按源工单序号升序，从目标的下一工单序号重新分配，并同步替换履历与
22	//     请求绑定中的工单引用；目标原有记录不改编号、不改变业务含义。
23	//   - 备件领用编号按源领用履历的全库序号整体排序（编号大小不代表领用先后），
24	//     从目标的下一领用序号重新分配并输出映射；领用记录的工单引用与退回履历中的
25	//     领用引用同步替换，数量、累计退回与净量保持。导入的未关闭工单可继续退回。
26	//   - 附件编号按源登记履历的全库序号整体排序，从目标的下一附件序号重新分配并
27	//     输出映射；附件记录的工单引用与登记、撤销履历中的附件引用同步替换，路径、
28	//     撤销状态、说明与理由保持。只复制索引，不复制资料文件；文件当前不可用不使
29	//     导入失败。
30	//   - 履历按源履历序号排列，在目标已有最大履历序号之后依次分配新序号，保留原操作
31	//     顺序（不按时间重排）；履历时间保留原瞬间与小数秒精度。导入本身不追加报修
32	//     或其他业务事件。
33	//   - 保养计划随资产原样复制（内容、首次到期日、间隔与下一到期日不变），保养履历
34	//     （含撤销履历）随资产履历一并复制，完成与撤销链自然接续，撤销履历中的目标
35	//     完成序号随履历重编号同步替换，并输出完成履历序号的原、新映射；目标已有计划
36	//     不受影响。导入后可用新完成序号继续撤销。
37	//   - 停用、恢复使用为资产级履历，随资产履历一并复制并重编号，资产当前的停用或
38	//     可用状态原样保留；导入后可继续恢复使用或停用。
39	//   - 资产编号在目标已存在，或所选工单的任一请求标识已在目标绑定时，整批拒绝：
40	//     不覆盖、不合并、不改请求标识。
41	//   - 操作前检查源、目标整库一致性，提交前由 save 再检查合并后的数据；整批变化
42	//     一次原子写入目标。任何失败都不改动两边原文件、不留下部分导入、不消耗目标编号。
43	
44	// stringListFlag 收集可重复的 --asset-id 参数。
45	type stringListFlag []string
46	
47	func (f *stringListFlag) String() string { return strings.Join(*f, ",") }
48	
49	func (f *stringListFlag) Set(v string) error {
50		*f = append(*f, v)
51		return nil
52	}
53	
54	// ticketRemap 记录一张工单的原编号与新编号。
55	type ticketRemap struct {
56		OldID string
57		NewID string
58	}
59	
60	// partRemap 记录一笔备件领用的原领用编号与新领用编号。
61	type partRemap struct {
62		OldID string
63		NewID string
64	}
65	
66	// attachRemap 记录一条附件索引的原附件编号与新附件编号。
67	type attachRemap struct {
68		OldID string
69		NewID string
70	}
71	
72	// completionRemap 记录一条保养完成履历的原全库序号与新全库序号。
73	type completionRemap struct {
74		OldSeq int
75		NewSeq int
76	}
77	
78	// importOutcome 为一次成功导入的结果摘要，用于输出。
79	type importOutcome struct {
80		assetIDs    []string
81		tickets     []ticketRemap
82		parts       []partRemap
83		attachments []attachRemap
84		completions []completionRemap
85		plans       int
86	}
