88	func cmdImport(args []string, w io.Writer) error {
89		var opts cmdOptions
90		var sourceDir string
91		var assetIDs stringListFlag
92		fs := newFlagSet("import", &opts)
93		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
94		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
95		if err := parseFlags(fs, args); err != nil {
96			return err
97		}
98		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
99			return err
100		}
101		if len(assetIDs) == 0 {
102			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
103		}
104		for _, id := range assetIDs {
105			if id == "" {
106				return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
107			}
108		}
109	
110		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
111		if err != nil {
112			return err
113		}
114		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
115		if outcome.plans > 0 {
116			fmt.Fprintf(w, "同时导入 %d 项保养计划及其保养履历。\n", outcome.plans)
117		}
118		if len(outcome.tickets) == 0 {
119			fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
120		} else {
121			fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
122			for _, m := range outcome.tickets {
123				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
124			}
125		}
126		if len(outcome.parts) > 0 {
127			fmt.Fprintln(w, "领用编号映射（原编号 -> 新编号）:")
128			for _, m := range outcome.parts {
129				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
130			}
131		}
132		if len(outcome.attachments) > 0 {
133			fmt.Fprintln(w, "附件编号映射（原编号 -> 新编号）:")
134			for _, m := range outcome.attachments {
135				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
136			}
137		}
138		if len(outcome.completions) > 0 {
139			fmt.Fprintln(w, "完成履历序号映射（原序号 -> 新序号）:")
140			for _, m := range outcome.completions {
141				fmt.Fprintf(w, "%d -> %d\n", m.OldSeq, m.NewSeq)
142			}
143		}
144		return nil
145	}
146	
147	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
148	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
149	// 两边原文件字节保持不变。
150	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
151		srcAbs, err := filepath.Abs(sourceDir)
152		if err != nil {
153			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
154		}
155		dstAbs, err := filepath.Abs(targetDir)
156		if err != nil {
157			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
158		}
159		if srcAbs == dstAbs {
160			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
161		}
162		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
163		srcPath := filepath.Join(srcAbs, dataFileName)
164		dstPath := filepath.Join(dstAbs, dataFileName)
165		if fi1, err1 := os.Stat(srcPath); err1 == nil {
166			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
167				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
168			}
169		}
170	
171		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
172		src, err := openSourceStore(srcAbs)
173		if err != nil {
174			return nil, err
175		}
176		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
177		dst, err := openStore(dstAbs)
178		if err != nil {
179			return nil, err
180		}
181		outcome, err := dst.mergeImport(src, assetIDs)
182		if err != nil {
183			return nil, err
184		}
185		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
186		if err := dst.save(); err != nil {
187			return nil, err
188		}
189		return outcome, nil
190	}
191	
192	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
193	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
194	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
195		// 重复编号按一项处理，保持首次出现的顺序。
196		selected := map[string]bool{}
197		ids := make([]string, 0, len(assetIDs))
198		for _, id := range assetIDs {
199			if !selected[id] {
200				selected[id] = true
201				ids = append(ids, id)
202			}
203		}
204		// 所选资产必须存在于源，且编号在目标中不存在。
205		assets := make([]*Asset, 0, len(ids))
206		for _, id := range ids {
207			a := src.findAsset(id)
208			if a == nil {
209				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
210			}
211			if s.findAsset(id) != nil {
212				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
213			}
214			assets = append(assets, a)
215		}
216		// 所选资产的全部工单，按源工单序号升序重新分配编号。
217		tickets := make([]*Ticket, 0)
218		for _, t := range src.data.Tickets {
219			if selected[t.AssetID] {
220				tickets = append(tickets, t)
221			}
222		}
223		sort.SliceStable(tickets, func(i, j int) bool {
224			ni, _ := parseTicketSeq(tickets[i].ID)
225			nj, _ := parseTicketSeq(tickets[j].ID)
226			return ni < nj
227		})
228		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
229		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
230			return nil, fmt.Errorf(
231				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
232				errConflict, s.data.NextTicketSeq, len(tickets))
233		}
234		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
235		srcReqByTicket := map[string]*requestBinding{}
236		for i := range src.data.Requests {
237			r := &src.data.Requests[i]
238			srcReqByTicket[r.TicketID] = r
239		}
240		for _, t := range tickets {
241			r := srcReqByTicket[t.ID]
242			if r == nil {
243				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
244			}
245			if s.findRequest(r.RequestID) != nil {
246				return nil, fmt.Errorf(
247					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
248			}
249		}
250		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
251		events := make([]Event, 0)
252		for _, e := range src.data.Events {
253			if selected[e.AssetID] {
254				events = append(events, e)
255			}
256		}
257		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
258		maxSeq := 0
259		for _, e := range s.data.Events {
260			if e.Seq > maxSeq {
261				maxSeq = e.Seq
262			}
263		}
264		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
265		if len(events) > math.MaxInt-maxSeq {
266			return nil, fmt.Errorf(
267				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
268				errConflict, maxSeq, len(events))
269		}
270		// 所选工单的全部备件领用记录，按源领用履历的全库序号整体排序（领用编号
271		// 只定位记录，编号大小不代表领用先后），再按此顺序重新分配领用编号。
272		srcTicketIDs := map[string]bool{}
273		for _, t := range tickets {
274			srcTicketIDs[t.ID] = true
275		}
276		srcWithdrawSeq := map[string]int{}
277		for _, e := range src.data.Events {
278			if e.Kind == eventPartWithdraw {
279				srcWithdrawSeq[e.WithdrawalID] = e.Seq
280			}
281		}
282		parts := make([]*PartWithdrawal, 0)
283		for _, p := range src.data.Parts {
284			if srcTicketIDs[p.TicketID] {
285				parts = append(parts, p)
286			}
287		}
288		sort.SliceStable(parts, func(i, j int) bool {
289			return srcWithdrawSeq[parts[i].ID] < srcWithdrawSeq[parts[j].ID]
290		})
291		// 领用编号容量：与 withdrawPart 同一约束，可分配的最大序号为 math.MaxInt-1。
292		if len(parts) > math.MaxInt-s.data.NextPartSeq {
293			return nil, fmt.Errorf(
294				"%w: 目标领用编号容量不足：下一序号 %d 无法容纳 %d 笔导入领用，整批拒绝导入",
295				errConflict, s.data.NextPartSeq, len(parts))
296		}
297		// 所选工单的全部附件索引（有效与已撤销都复制），按源登记履历的全库序号
298		// 整体排序（附件编号只定位记录，编号大小不代表登记先后），再按此顺序重新
299		// 分配附件编号。只复制索引记录与履历，不复制资料文件；文件当前不可用不使
300		// 导入失败。
301		srcAttachRegSeq := map[string]int{}
302		for _, e := range src.data.Events {
303			if e.Kind == eventAttach {
304				srcAttachRegSeq[e.AttachmentID] = e.Seq
305			}
306		}
307		attachments := make([]*Attachment, 0)
308		for _, a := range src.data.Attachments {
309			if srcTicketIDs[a.TicketID] {
310				attachments = append(attachments, a)
311			}
312		}
313		sort.SliceStable(attachments, func(i, j int) bool {
314			return srcAttachRegSeq[attachments[i].ID] < srcAttachRegSeq[attachments[j].ID]
315		})
316		// 附件编号容量：与 attach 同一约束，可分配的最大序号为 math.MaxInt-1。
317		if len(attachments) > math.MaxInt-s.data.NextAttachSeq {
318			return nil, fmt.Errorf(
319				"%w: 目标附件编号容量不足：下一序号 %d 无法容纳 %d 条导入附件索引，整批拒绝导入",
320				errConflict, s.data.NextAttachSeq, len(attachments))
321		}
322	
323		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
324		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
325		for _, a := range assets {
326			na := *a
327			s.data.Assets = append(s.data.Assets, &na)
328		}
329		// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
330		// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
331		planCount := 0
332		for _, p := range src.data.Plans {
333			if selected[p.AssetID] {
334				np := *p
335				s.data.Plans = append(s.data.Plans, &np)
336				planCount++
337			}
338		}
339		outcome := &importOutcome{assetIDs: ids, plans: planCount}
340		remap := map[string]string{}
341		next := s.data.NextTicketSeq
342		for _, t := range tickets {
343			nt := *t
344			nt.ID = fmt.Sprintf("T%04d", next)
345			remap[t.ID] = nt.ID
346			s.data.Tickets = append(s.data.Tickets, &nt)
347			r := srcReqByTicket[t.ID]
348			s.data.Requests = append(s.data.Requests, requestBinding{
349				RequestID:   r.RequestID,
350				AssetID:     r.AssetID,
351				Description: r.Description,
352				TicketID:    nt.ID,
353			})
354			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
355			next++
356		}
357		s.data.NextTicketSeq = next
358		// 备件领用记录按源领用顺序重新分配领用编号，工单引用同步替换；
359		// 数量、累计退回与说明等业务信息原样保留。
360		partIDs := map[string]string{}
361		nextPart := s.data.NextPartSeq
362		for _, p := range parts {
363			np := *p
364			np.ID = fmt.Sprintf("P%04d", nextPart)
365			np.TicketID = remap[p.TicketID]
366			partIDs[p.ID] = np.ID
367			s.data.Parts = append(s.data.Parts, &np)
368			outcome.parts = append(outcome.parts, partRemap{OldID: p.ID, NewID: np.ID})
369			nextPart++
370		}
371		s.data.NextPartSeq = nextPart
372		// 附件索引按源登记顺序重新分配附件编号，工单引用同步替换；
373		// 路径、撤销状态、说明与撤销理由等业务信息原样保留。
374		attachIDs := map[string]string{}
375		nextAttach := s.data.NextAttachSeq
376		for _, a := range attachments {
377			na := *a
378			na.ID = fmt.Sprintf("A%04d", nextAttach)
379			na.TicketID = remap[a.TicketID]
380			attachIDs[a.ID] = na.ID
381			s.data.Attachments = append(s.data.Attachments, &na)
382			outcome.attachments = append(outcome.attachments, attachRemap{OldID: a.ID, NewID: na.ID})
383			nextAttach++
384		}
385		s.data.NextAttachSeq = nextAttach
386		seq := maxSeq
387		seqRemap := map[int]int{}
388		for _, e := range events {
389			seq++
390			ne := e
391			ne.Seq = seq
392			ne.TicketID = remap[e.TicketID]
393			ne.WithdrawalID = partIDs[e.WithdrawalID]
394			ne.AttachmentID = attachIDs[e.AttachmentID]
395			if e.Kind == eventPlanRevoke {
396				// 撤销履历的目标完成序号随履历重编号同步替换：目标在源序号顺序中
397				// 先于撤销出现（源台账已通过一致性检查），此处必然已有映射。
398				ne.TargetSeq = seqRemap[e.TargetSeq]
399			}
400			seqRemap[e.Seq] = seq
401			if e.Kind == eventPlanDone {
402				outcome.completions = append(outcome.completions, completionRemap{OldSeq: e.Seq, NewSeq: seq})
403			}
404			s.data.Events = append(s.data.Events, ne)
405		}
406		return outcome, nil
407	}
408

