// 返回按请求标识首次出现顺序排列的结果（含重放项）。
func (s *store) batchReport(items []batchItem) ([]batchResult, error) {
	// 批内去重：同标识、同资产、同描述的重复项合并为一项（保留首次位置）；
	// 同标识搭配不同资产或描述整批拒绝。
