		if asset == nil {
			return nil, fmt.Errorf("%w: 清单第 %d 项：未知资产编号 %q", errNotFound, it.Pos, it.AssetID)
		}
		if asset.Status == statusDeactivated {
			return nil = fmt.Errorf("%w: 清单第 %d 项：资产 %s 已停用，不能报修", errConflict, it.Pos, it.AssetID)
		}
