// 末项失败：前面的新请求都合法，最后一项资产未知，整批失败，
// 不留下部分记录或请求绑定、不消耗编号，台账字节不变。
func TestBatchReportLastItemFails(t *testing.T) {
	dir := t.TempDir()
	s := newStoreAt(t, dir)
	for _, a := range [][3]string{{"EQ-1", "打印机", "一楼"}, {"EQ-2", "空调", "二楼"}} {
		if _, err := s.registerAsset(a[0], a[1], a[2]); err != nil {
			t.Fatal(err)
		}
	}
